    imageHint: "Veluwezoom national park heather field",
    descriptionAdvanced: {
      de: "Der Nationalpark Veluwezoom, gegründet 1930, war der erste Nationalpark der Niederlande und ist eines der meistbesuchten Naturgebiete des Landes. Er liegt am Südrand der Veluwe-Moräne in Gelderland und weist eine für die Niederlande ungewöhnlich hügelige Landschaft auf, wobei der Aussichtspunkt Posbank 90 Meter über den Meeresspiegel reicht. Das Gelände ist eine Mischung aus alten Laubwäldern, weiten Heideflächen und dramatischen Sandverwehungen, die während der letzten Eiszeit entstanden sind. Der Park wird von Natuurmonumenten verwaltet und konzentriert sich darauf, natürliche Prozesse die Landschaft formen zu lassen, was zu einer hohen Biodiversität führt. Große Säugetiere wie Edelhirsche, Wildschweine und Damhirsche streifen frei umher, und die Heideblüte im August färbt die Hügel in ein leuchtendes Violett. Historisch war das Gebiet Teil verschiedener Landgüter, deren Reste noch heute zu finden sind.",
      hu: "A Veluwezoom Nemzeti Parkot 1930-ban alapították, Hollandia első nemzeti parkja volt, és továbbra is az ország egyik leglátogatottabb természeti területe. Gelderland tartományban, a Veluwe-moréna déli szélén található, Hollandiára nem jellemző dombos tájjal rendelkezik, a Posbank kilátó 90 méterrel magasodik a tengerszint fölé. A terep ősi lombhullató erdők, hatalmas fenyérek és drámai homokvándorlások keveréke, amelyek az utolsó jégkorszakban alakultak ki. A parkot a Natuurmonumenten kezeli, és arra összpontosít, hogy a természetes folyamatok alakítsák a tájat, ami magas szintű biodiverzitáshoz vezet. Nagyemlősök, például gímszarvasok, vaddisznók és dámvadak szabadon kószálnak, az augusztusi fenyérvirágzás pedig élénk lilára festi a dombokat. Történelmileg a terület különféle birtokok része volt, amelyek udvarházainak és parkjainak maradványai ma is fellelhetők.",
      ro: "Parcul Național Veluwezoom, înființat în 1930, a fost primul parc național din Țările de Jos și rămâne una dintre cele mai vizitate zone naturale din țară. Situat la marginea sudică a morenei Veluwe din Gelderland, prezintă un peisaj neobișnuit de deluros pentru Țările de Jos, punctul de observație Posbank atingând 90 de metri deasupra nivelului mării. Terenul este un amestec de păduri antice de foioase, pajiști vaste de iarbă neagră și dune de nisip dramatice care s-au format în timpul ultimei perioade glaciare. Parcul este administrat de Natuurmonumenten și se concentrează pe permiterea proceselor naturale să modeleze peisajul. Mamifere mari, cum ar fi cerbii comuni, mistreții și căprioarele lopătar, hoinăresc libere, iar înflorirea ierbii negre în august acoperă dealurile în mov. Din punct de vedere istoric, zona a făcut parte din diverse domenii nobiliare.",
      en: "Veluwezoom National Park, established in 1930, was the first national park in the Netherlands and remains one of the most visited natural areas in the country. Located on the southern edge of the Veluwe moraine in Gelderland, it features an uncharacteristically hilly landscape for the Netherlands, with the Posbank viewpoint reaching 90 meters above sea level. The terrain is a mix of ancient deciduous forests, vast heathlands, and dramatic sand drifts that were formed during the last glacial period. The park is managed by Natuurmonumenten and focuses on allowing natural processes to shape the landscape, leading to a high level of biodiversity. Large mammals such as red deer, wild boar, and fallow deer roam freely, and the blooming of the heather in August covers the hills in a vibrant purple. Historically, the area was part of various estates, and remnants of these manor houses still exist.",
      es: "El Parque Nacional Veluwezoom, en la provincia de Gelderland, es el parque nacional más antiguo de los Países Bajos, fundado en 1930. Se extiende sobre unas 5.600 hectáreas y forma parte de la región más amplia de Veluwe. El paisaje es variado, con bosques, brezales, dunas de arena y valles fluviales. El parque alberga ciervos rojos, jabalíes y muflones. El centro de visitantes en Rheden ofrece información sobre la naturaleza. Es especialmente conocido el mirador \"Posbank\", con una vista panorámica amplia. El área es gestionada por Natuurmonumenten.",
      pt: "O Parque Nacional Veluwezoom, na província de Gelderland, é o parque nacional mais antigo dos Países Baixos, fundado em 1930. Estende-se por cerca de 5.600 hectares e faz parte da região mais ampla de Veluwe. A paisagem é variada, com florestas, urzes, dunas de areia e vales fluviais. O parque alberga veados, javalis e muflões. O centro de visitantes em Rheden oferece informações sobre a natureza. O miradouro \"Posbank\" é particularmente conhecido, oferecendo uma vista ampla. A área é gerida pela Natuurmonumenten.",
      fr: "Le parc national de Veluwezoom, dans la province de Gueldre, est le plus ancien parc national des Pays-Bas, fondé en 1930. Il s'étend sur environ 5 600 hectares et fait partie de la plus grande région de Veluwe. Le paysage est varié avec des forêts, des landes, des bancs de sable et des vallées fluviales. Le parc abrite des cerfs élaphes, des sangliers et des mouflons. Le centre d'accueil de Rheden informe sur la nature. Le point de vue « Posbank », offrant un large panorama, est particulièrement célèbre. La zone est gérée par Natuurmonumenten.",
    },
