    imageHint: "Oostvaardersplassen landscape with wild horses",
    descriptionAdvanced: {
      de: "Die Oostvaardersplassen sind ein einzigartiges Naturschutzgebiet in der Provinz Flevoland, auf Land, das in den 1960er Jahren dem Meer abgerungen wurde. Ursprünglich für industrielle Zwecke vorgesehen, wurde das Gebiet unberührt gelassen und entwickelte sich schnell zu einem riesigen Feuchtgebiet, das tausende Wasservögel anzog. Das Reservat wird oft als neue Wildnis bezeichnet und ist berühmt für sein großangelegtes Rewilding-Experiment mit Heckrindern, Konik-Pferden und Edelhirschen. Diese großen Pflanzenfresser werden eingesetzt, um die Vegetation offen zu halten und die Bedingungen prähistorischer europäischer Landschaften nachzuahmen. Das Gebiet ist ein lebenswichtiger Lebensraum für den Seeadler, der hier 2006 zum ersten Mal seit über einem Jahrhundert in den Niederlanden wieder brütete. Das Management der Tierpopulationen war jedoch Gegenstand erheblicher öffentlicher Debatten, was zu Änderungen in der Strategie führte.",
      hu: "Az Oostvaardersplassen egy egyedülálló természetvédelmi terület Flevoland tartományban, az 1960-as években a tengertől elhódított területen. Eredetileg ipari célokra szánták, de a területet érintetlenül hagyták, és gyorsan hatalmas vizes élőhellyé fejlődött, amely vízimadarak ezreit vonzotta. A rezervátumot gyakran 'új vadonként' emlegetik, és híres a heck-marhák, konik-lovak és gímszarvasok bevonásával végzett nagyszabású vadvisszatelepítési kísérletéről. Ezeket a nagytestű növényevőket a vegetáció nyitottan tartására használják, a történelem előtti európai tájak körülményeit utánozva. A terület létfontosságú élőhelye a rétisasnak, amely 2006-ban fészkelt itt először Hollandiában több mint egy évszázad után. Az állatpopulációk kezelése azonban jelentős lakossági vita tárgyát képezte, ami a stratégia megváltoztatásához vezetett.",
      ro: "Oostvaardersplassen este o rezervație naturală unică în provincia Flevoland, situată pe terenuri recuperate din mare în anii 1960. Destinată inițial pentru uz industrial, zona a fost lăsată neatinsă și s-a transformat rapid într-o zonă umedă vastă care a atras mii de păsări de apă. Rezervația este adesea descrisă ca o „nouă sălbăticie” și este faimoasă pentru experimentul său de rewilding la scară largă care implică vite Heck, cai Konik și cerbi. Aceste erbivore mari sunt folosite pentru a menține vegetația deschisă, imitând condițiile peisajelor europene preistorice. Zona este un habitat vital pentru vulturul codalb, care a început să cuibărească aici în 2006 pentru prima dată în Țările de Jos după mai bine de un secol. Cu toate acestea, gestionarea populațiilor de animale a fost subiectul unor dezbateri publice.",
      en: "The Oostvaardersplassen is a unique nature reserve located in the province of Flevoland, situated on land reclaimed from the sea in the 1960s. Originally intended for industrial use, the area was left untouched and quickly developed into a vast wetland that attracted thousands of water birds. The reserve is often described as a 'new wilderness' and is famous for its large-scale rewilding experiment involving Heck cattle, Konik horses, and red deer. These large herbivores are used to keep the vegetation open, mimicking the conditions of prehistoric European landscapes. The area is a vital habitat for the white-tailed eagle, which began breeding here in 2006 for the first time in the Netherlands in over a century. However, the management of the animal populations has been a subject of significant public debate, leading to changes in the park's ecological strategies.",
      es: "Las Oostvaardersplassen, en la provincia de Flevoland, son un humedal de 5.600 hectáreas que surgió tras la creación de diques en el IJsselmeer en la década de 1960. Es una importante zona de protección de aves con relevancia internacional para aves acuáticas como la avoceta y la garza blanca. El paisaje es abierto, con praderas, pantanos y aguas abiertas. Una famosa manada de caballos Konik y ciervos rojos gestiona el área de forma natural. Las Oostvaardersplassen son un ejemplo de procesos dinámicos en la naturaleza. Los visitantes pueden realizar observaciones desde plataformas de avistamiento.",
      pt: "As Oostvaardersplassen, na província de Flevoland, são uma zona húmida de 5.600 hectares que surgiu após a construção de diques no IJsselmeer na década de 1960. É uma importante área de proteção de aves com relevância internacional para aves aquáticas como o alfaiate e a garça-branca. A paisagem é aberta, com prados, pântanos e águas abertas. Uma famosa manada de cavalos Konik e veados gere a área naturalmente. As Oostvaardersplassen são um exemplo de processos dinâmicos na natureza. Os visitantes podem observar através de plataformas de observação.",
      fr: "L'Oostvaardersplassen, dans la province de Flevoland, est une zone humide de 5 600 hectares qui a vu le jour après l'endiguement de l'IJsselmeer dans les années 1960. C'est une zone de protection des oiseaux importante, d'envergure internationale pour les oiseaux d'eau tels que l'avocette élégante et la grande aigrette. Le paysage est ouvert avec des prairies, des marais et des eaux libres. Un célèbre troupeau de chevaux Konik et de cerfs élaphes entretient la zone naturellement. L'Oostvaardersplassen est un exemple de processus dynamiques dans la nature. Les visiteurs peuvent faire des observations depuis des plateformes dédiées.",
    },
    factsAdvanced: {
      de: ["Das Gebiet liegt auf dem Boden der ehemaligen Zuiderzee.", "Die Oostvaardersplassen umfassen etwa 5.600 Hektar Land.", "Der Seeadler brütete hier 2006 erstmals wieder in den Niederlanden.", "Tausende Konik-Pferde und Heckrinder leben halbwild im Reservat.", "Das Gebiet dient als wichtiger Rastplatz für zehntausende Graugänse.", "Der Dokumentarfilm 'De Nieuwe Wildernis' aus 2013 machte das Gebiet weltbekannt."],
      hu: ["A terület a korábbi Zuiderzee fenekén fekszik.", "Az Oostvaardersplassen körülbelül 5600 hektárnyi területet foglal el.", "A rétisas 2006-ban fészkelt itt először újra Hollandiában.", "Konik lovak és heck-marhák ezrei élnek félvadon a rezervátumban.", "A terület fontos pihenőhely több tízezer nyári lúd számára.", "A 2013-as 'De Nieuwe Wildernis' dokumentumfilm tette világszerte ismertté."],
      ro: ["Zona este situată pe fundul fostei mări Zuiderzee.", "Oostvaardersplassen cuprinde aproximativ 5.600 de hectare de teren.", "Vulturul codalb a cuibărit aici în 2006 pentru prima dată după un secol.", "Mii de cai Konik și vite Heck trăiesc în stare semi-sălbatică în rezervație.", "Zona servește ca loc de popas crucial pentru mii de gâște de vară.", "Documentarul 'De Nieuwe Wildernis' din 2013 a prezentat ecosistemul parcului."],
      en: ["The reserve is located on the polder of South Flevoland, created in 1968.", "The core area of the reserve covers approximately 56 square kilometers.", "White-tailed eagles have been breeding in the park annually since 2006.", "The Heck cattle were bred to resemble the extinct wild aurochs.", "Around 30,000 pairs of greylag geese use the area for molting each year.", "The area is divided into a wet marshland and a dry grassland section."],
      es: ["Superficie: 5.600 hectáreas (56 km²)", "Surgido en la década de 1960 tras el dique", "Aprox. 4.000 caballos Konik en el área", "Parejas reproductoras de avocetas: más de 1.000", "Parte de la red Natura 2000", "500.000 visitantes anuales"],
      pt: ["Área: 5.600 hectares (56 km²)", "Surgida na década de 1960 após a construção de diques", "Cerca de 4.000 cavalos Konik na área", "Casais reprodutores de alfaiates: mais de 1.000", "Parte da rede Natura 2000", "500.000 visitantes anuais"],
      fr: ["Superficie : 5 600 hectares (56 km²)", "Créé dans les années 1960 après endiguement", "Environ 4 000 chevaux Konik dans la zone", "Couples d'avocettes nicheurs : plus de 1 000", "Fait partie du réseau Natura 2000", "500 000 visiteurs par an"],
    },
