      en: ["Largest fen mire in NW Europe", "Total area exceeds 10,000 hectares", "Otters reintroduced successfully in 2002", "Includes the famous village of Giethoorn", "Primary habitat for the large copper butterfly", "The two areas merged officially in 2009"],
      es: ["Superficie: 10.000 hectáreas (100 km²)", "Siega de juncos: 1.200 ha anuales", "Parejas de aguilucho lagunero: unas 50", "Rutas en canoa: 150 km", "Parte del parque nacional desde 2009", "200.000 visitantes anuales"],
      pt: ["Área: 10.000 hectares (100 km²)", "Ceifa de caniços: 1.200 ha por ano", "Casais de tartaranhão: cerca de 50", "Rotas de canoa: 150 km", "Parte do Parque Nacional desde 2009", "200.000 visitantes por ano"],
