      de: ["Frühere Meeresbucht", "Vogelzuggebiet", "Dark Sky Park", "Süßwassersee"],
      hu: ["Korábbi tengeröböl", "Madárvonulási terület", "Dark Sky Park", "Édesvizű tó"],
