    imageHint: "Lauwersmeer lake sunset",
    descriptionAdvanced: {
      de: "Der Nationalpark Lauwersmeer, an der Grenze zwischen den Provinzen Groningen und Friesland gelegen, entstand durch eine der spektakulärsten Landschaftsveränderungen der Niederlande. Ursprünglich ein offener Meeresarm der Wattensee, wurde die Lauwerszee 1969 aus Angst vor Überschwemmungen durch einen Deich vom Meer getrennt und in einen Süßwassersee umgewandelt. In den folgenden Jahrzehnten entwickelte sich auf dem ehemaligen Meeresboden eine Wildnis aus Schilfgebieten, Wäldern und offenen Wasserflächen, die heute als Nationalpark (seit 2003) geschützt ist. Das Gebiet ist ein Paradies für Ornithologen, da es auf der Route vieler Zugvögel liegt und Brutplatz für den Seeadler ist, der hier seit 2004 wieder heimisch ist. Zur Landschaftspflege werden große Weidetiere wie Konik-Pferde und schottische Hochlandrinder eingesetzt, die die Vegetation kurz halten. Im Jahr 2016 wurde der Park zudem als \"Dark Sky Park\" zertifiziert, was ihn zu einem der wenigen Orte in Europa macht, an denen absolute Dunkelheit und ein ungetrübter Sternenhimmel erlebbar sind.",
      hu: "A Lauwersmeer Nemzeti Park Groningen és Friesland tartományok határán fekszik, és Hollandia egyik legjelentősebb tájátalakítási projektjének eredménye. Eredetileg a Waddenzee nyitott öble volt, ám az 1953-as árvíz utáni biztonsági intézkedések részeként 1969-ben egy gáttal elzárták a tengertől, így az sós vízi öbölből édesvizű tóvá alakult. Az egykori tengerfenéken azóta hatalmas nádasok, rétek és erdők jöttek létre, amelyeket 2003 óta nemzeti parkként védenek. A terület az ornitológusok paradicsoma: a madárvonulási útvonalak fontos állomása, és 2004 óta ismét fészkel itt a rétisas. A táj nyitottságának megőrzése érdekében Konik lovak és skót felföldi marhák legelnek szabadon a területen. 2016-ban a park megkapta a \"Sötét Égbolt Park\" minősítést, elismerve, hogy ez az egyik kevés hely Európában, ahol a fényszennyezés hiánya miatt tökéletesen látható a csillagos égbolt.",
      ro: "Parcul Național Lauwersmeer, situat la granița dintre provinciile Groningen și Friesland, este rezultatul uneia dintre cele mai dramatice transformări teritoriale din Țările de Jos. Inițial un braț deschis al Mării Wadden, golful Lauwerszee a fost închis în 1969 prin construirea unui dig pentru a preveni inundațiile, transformându-se treptat într-un lac cu apă dulce. Pe fostul fund al mării s-a dezvoltat o sălbăticie spectaculoasă de stufărișuri, păduri tinere și pajiști, protejate sub statut de parc național din 2003. Regiunea este un refugiu critic pentru păsările migratoare și un loc de cuibărit pentru vulturul codalb, care a revenit aici în 2004. Pentru a preveni împădurirea spontană a zonelor deschise, pe pajiști pasc libere herghelii de cai Konik și vite scoțiene Highland. În 2016, parcul a primit certificarea de \"Dark Sky Park\", fiind unul dintre puținele locuri din Europa unde întunericul natural este protejat, permițând observarea clară a Căii Lactee.",
      en: "Lauwersmeer National Park, located on the border of Groningen and Friesland, is the result of a significant man-made environmental shift. Originally a tidal inlet of the Wadden Sea, the Lauwerszee was dammed in 1969 for flood protection, transforming it into a freshwater lake environment. Over the subsequent decades, the former seabed evolved into a rich wilderness of reed beds, grasslands, and young forests, designated as a national park in 2003. The area is a haven for birdwatchers, serving as a vital stopover for migratory birds and a breeding ground for the white-tailed eagle, which returned to the area in 2004. To maintain the open character of the landscape, large herbivores such as Konik horses and Highland cattle are used for natural grazing. In 2016, the park was officially designated a Dark Sky Park, recognizing it as one of the few places in Europe where natural darkness is preserved for exceptional stargazing.",
      es: "El Lauwersmeer, en la provincia de Groninga/Frisia, es una zona de parque nacional de 9.000 hectáreas que se creó en 1969 mediante la desecación de la Lauwerszee. Es un humedal importante para aves acuáticas, especialmente para gansos y patos. El paisaje es variado, con aguas abiertas, cinturones de juncos, prados y bosques. El parque alberga plantas poco comunes como el aster de playa. La zona es un importante lugar de descanso para aves migratorias en la ruta migratoria del Atlántico. Los visitantes pueden practicar senderismo, ciclismo y observación de aves acuáticas. El centro de visitantes de Lauwersoog ofrece información detallada.",
      pt: "O Lauwersmeer, na província de Groningen/Frísia, é uma área de parque nacional de 9.000 hectares que surgiu em 1969 através do represamento da Lauwerszee. É uma zona húmida importante para aves aquáticas, especialmente gansos e patos. A paisagem é variada, com águas abertas, cinturões de caniços, prados e florestas. O parque abriga plantas raras como a áster-marítima. A área é um importante local de repouso para aves migratórias na rota migratória do Atlântico. Os visitantes podem caminhar, andar de bicicleta e observar aves aquáticas. O centro de visitantes em Lauwersoog oferece informações.",
      fr: "Le Lauwersmeer, situé dans la province de Groningue/Frise, est un parc national de 9 000 hectares créé en 1969 par l'endiguement de la Lauwerszee. C'est une zone humide majeure pour les oiseaux d'eau, en particulier les oies et les canards. Le paysage est diversifié, alternant eaux libres, roselières, prairies et forêts. Le parc abrite des plantes rares telles que l'aster maritime. La zone est une halte migratoire importante pour les oiseaux sur la voie de l'Atlantique. Les visiteurs peuvent y pratiquer la randonnée, le cyclisme et l'observation ornithologique. Le centre d'accueil de Lauwersoog fournit toutes les informations nécessaires.",
    },
