      ro: ["Fost fund de mare (diguit în 1969)", "Statut de parc național din 2003", "Certificat ca Dark Sky Park în 2016", "Cuibăritul vulturului codalb din 2004", "Suprafață de aproximativ 6000 de hectare", "Gestionat prin pășunatul cailor Konik"],
      en: ["Former seabed reclaimed in 1969", "National Park status since 2003", "Certified Dark Sky Park since 2016", "Breeding ground for white-tailed eagles", "Covers approximately 6000 hectares", "Naturally grazed by Konik horses"],
