      es: ["Superficie: 4.500 hectáreas", "Parque nacional: fundado en 1996", "Duna más alta: 30 metros sobre el NAP", "Número de especies vegetales: 400", "Especies de aves: 150", "Sendero: 100 km de rutas señalizadas"],
      pt: ["Área: 4.500 hectares", "Parque nacional: fundado em 1996", "Duna mais alta: 30 metros acima do NAP", "Número de espécies de plantas: 400", "Espécies de aves: 150", "Trilho: 100 km de rotas marcadas"],
      fr: ["Superficie : 4 500 hectares", "Parc national : fondé en 1996", "Plus haute dune : 30 mètres au-dessus du NAP", "Nombre d'espèces végétales : 400", "Espèces d'oiseaux : 150", "Sentier de randonnée : 100 km de parcours balisés"],
